import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
export function checkCloudProject(root = process.cwd()) {
  const required = ['package-lock.json', 'www/index.html', 'www/seed.zip', 'www/seed-version.json', 'ios/App/App.xcodeproj/project.pbxproj', 'ios/App/App.xcodeproj/xcshareddata/xcschemes/App.xcscheme', 'ios/App/ci_scripts/ci_post_clone.sh', 'ios/App/App.xcodeproj/project.xcworkspace/xcshareddata/swiftpm/Package.resolved'];
  const missing = required.filter(name => !existsSync(resolve(root, name)));
  if (missing.length) throw Error('Before pushing to Xcode Cloud, create/commit: ' + missing.join(', ') + '. Run npm run ios:setup and open Xcode to resolve Swift packages; see XCODE_CLOUD.md.');
  const pkg = JSON.parse(readFileSync(resolve(root, 'package.json'), 'utf8'));
  const lock = JSON.parse(readFileSync(resolve(root, 'package-lock.json'), 'utf8'));
  if (pkg.dependencies['@yissok/ios-web-runtime'] !== lock.packages?.['']?.dependencies?.['@yissok/ios-web-runtime']) throw Error('Runtime lockfile is stale. Run npm install and commit package-lock.json.');
  const pins = JSON.parse(readFileSync(resolve(root, required[7]), 'utf8')).pins || [];
  for (const [identity, version] of [['capacitor-swift-pm', '8.5.2'], ['zipfoundation', '0.9.20']]) {
    if (!pins.some(pin => pin.identity === identity && pin.state?.version === version && /^[a-f0-9]{40}$/.test(pin.state?.revision || ''))) throw Error('Resolve the pinned ' + identity + ' ' + version + ' in Xcode, then commit Package.resolved.');
  }
  const scheme = readFileSync(resolve(root, required[5]), 'utf8');
  if (!scheme.includes('buildForArchiving="YES"') || !scheme.includes('<ArchiveAction')) throw Error('The shared App scheme needs its Archive action enabled in Xcode.');
  if (!readFileSync(resolve(root, 'cloud/ci_post_clone.sh')).equals(readFileSync(resolve(root, required[6])))) throw Error('Cloud hook is stale. Run npm run ios:cloud-prepare and commit both copies.');
  if (!(statSync(resolve(root, required[6])).mode & 0o111)) throw Error('Make ios/App/ci_scripts/ci_post_clone.sh executable and commit its file mode.');
  console.log('Repository files are ready. Configure the first workflow, source access, and secret in Xcode using XCODE_CLOUD.md.');
}
if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) checkCloudProject();
